CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone_number text UNIQUE NOT NULL, name text, email text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contact_id uuid UNIQUE NOT NULL REFERENCES contacts(id) ON DELETE CASCADE, current_state text NOT NULL DEFAULT 'NEW', automation_enabled boolean NOT NULL DEFAULT true, draft jsonb NOT NULL DEFAULT '{}'::jsonb, last_customer_message_at timestamptz, follow_up_due_at timestamptz, follow_up_status text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contact_id uuid NOT NULL REFERENCES contacts(id) ON DELETE CASCADE, whatsapp_message_id text UNIQUE, direction text NOT NULL CHECK(direction IN ('incoming','outgoing')), message_type text NOT NULL, content text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contact_id uuid NOT NULL REFERENCES contacts(id), request_key text UNIQUE NOT NULL, name text NOT NULL, phone_number text NOT NULL, treatment text NOT NULL, preferred_date text NOT NULL, preferred_time text NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','confirmed','cancelled')), notes text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_followups_due ON conversations(follow_up_due_at) WHERE follow_up_status = 'pending';

